head.b:skin:
:root { --ink:#503744; --rose:#934365; --gold:#886425; --line:#ead8df; }
* { box-sizing:border-box; }
html { scroll-padding-top:24px; }
body { margin:0; color:var(--ink); font:16px/1.8 'Trebuchet MS',Arial,sans-serif;
  background:radial-gradient(ellipse at 5% 0%,#fae4ec,transparent 45%),
  radial-gradient(ellipse at 100% 20%,#fff0d6,transparent 40%),#fffaf7; }
.wrap { max-width:980px; margin:auto; padding:28px 20px 12px; }
.brand { display:flex; align-items:center; gap:12px; margin:0 4px 22px;
  font-size:21px; font-weight:bold; letter-spacing:-.6px; }
.brand-mark { display:grid; place-items:center; width:46px; height:46px;
  background:#fff; border:1px solid var(--line); border-radius:17px;
  color:var(--rose); box-shadow:0 5px 15px #b87c9210; font-size:28px; }
.brand small { display:block; font-size:10px; letter-spacing:1.7px;
  color:var(--gold); text-transform:uppercase; font-weight:normal; }
.hero { position:relative; overflow:hidden; padding:38px; border-radius:34px;
  background:linear-gradient(125deg,#fbe5ed,#fff8ec 70%,#f4eafb);
  border:1px solid #e8cdd8; box-shadow:0 14px 45px #9c58720d; }
.hero::before { content:''; position:absolute; inset:8px; border:1px solid #ffffffc9;
  border-radius:27px; pointer-events:none; }
.hero-row { position:relative; display:flex; align-items:center; gap:20px; }
.hero-copy { flex:1; min-width:0; }
.eyebrow { color:var(--gold); font-size:11px; font-weight:bold;
  letter-spacing:1.6px; text-transform:uppercase; }
h1 { margin:14px 0; font-size:44px; line-height:1.12; letter-spacing:-1.6px; }
.hero-copy p { max-width:430px; font-size:15px; line-height:1.7; }
.date { display:inline-block; padding:5px 13px; background:#ffffffb8;
  border:1px solid #e4cfae; border-radius:30px; color:#785a32; font-size:12px; }
.pals-art { flex:0 0 220px; width:220px; height:220px; }
nav { position:relative; display:flex; flex-wrap:wrap; gap:10px; margin-top:26px; }
a { color:#873655; text-underline-offset:4px; overflow-wrap:anywhere; }
nav a { display:flex; align-items:center; gap:8px; min-height:44px; padding:9px 15px;
  background:#ffffffd9; border:1px solid #e4d4dd; border-radius:16px;
  text-decoration:none; font-size:13px; font-weight:bold; transition:background .15s; }
nav a:hover { background:#f6deea; }
nav a span { color:var(--rose); font-size:16px; }
a:focus-visible { outline:3px solid var(--rose); outline-offset:4px; }
.care-note { display:flex; align-items:center; gap:13px; margin:20px 5px 26px;
  font-size:13px; line-height:1.6; }
.care-note span { flex-shrink:0; color:var(--rose); font-size:26px; }
article,.contact { margin-top:22px; padding:34px 38px; background:#fffefd;
  border:1px solid var(--line); border-radius:28px; box-shadow:0 10px 30px #9c587207; }
.section-tag { display:inline-flex; align-items:center; gap:8px; border-radius:12px;
  padding:5px 11px; background:#f9e8ef; color:var(--rose); font-size:11px;
  font-weight:bold; letter-spacing:1px; text-transform:uppercase; }
h2 { color:var(--rose); margin:14px 0 20px; font-size:29px; line-height:1.3;
  letter-spacing:-.7px; }
h3 { margin:30px 0 12px; padding-top:22px; border-top:1px solid #f1e6e9;
  font-size:18px; line-height:1.45; }
p,ul { margin:12px 0; }
article p { max-width:76ch; }
.contact { background:linear-gradient(125deg,#fff3db,#fffaf4 65%,#f9eaf0); }
.contact p { margin-bottom:18px; }
.mail-button { display:inline-flex; align-items:center; justify-content:center;
  min-height:46px; padding:10px 18px; background:var(--rose); border-radius:16px;
  color:#fff; text-decoration:none; font-size:14px; font-weight:bold; }
footer { text-align:center; padding:26px 0; color:#765768; font-size:12px; }
footer a { display:inline-block; margin-top:7px; }
#policyLayout { display:none; }
@media (max-width:600px) {
  .wrap { padding:18px 14px 8px; }
  .brand { margin-bottom:17px; }
  .hero { padding:28px 24px 24px; border-radius:28px; }
  .hero-row { flex-direction:column; align-items:flex-start; gap:8px; }
  h1 { font-size:36px; }
  .pals-art { flex:none; align-self:center; width:176px; height:164px; }
  nav { gap:8px; margin-top:12px; }
  nav a { flex:1 1 42%; padding:9px 11px; font-size:12px; }
  article,.contact { padding:26px 23px; border-radius:25px; }
  h2 { font-size:26px; } h3 { font-size:17px; }
  body { font-size:15px; }
  .mail-button { max-width:100%; font-size:12px; }
}
@media (prefers-reduced-motion:reduce) { * { transition:none!important; } }
@media print {
  body { background:white; color:black; } .wrap { max-width:none; padding:0; }
  nav,.pals-art,.care-note,footer { display:none; }
  .hero,article,.contact { border:0; background:white; box-shadow:none; padding:0; }
  .hero::before { display:none; } .mail-button { color:black; background:white; }
}
